import { log } from "../log.js";
import { renameSync, rmSync, writeFileSync } from "node:fs";
// src/utils/json_file.ts
/** Renames a temporary file into place so a concurrent reader never sees a partial write. */
const writeJsonFile = (path, value, description) => {
	const temporaryPath = `${path}.${process.pid}.tmp`;
	try {
		writeFileSync(temporaryPath, `${JSON.stringify(value)}\n`, { mode: 384 });
		renameSync(temporaryPath, path);
		return true;
	} catch (error) {
		try {
			rmSync(temporaryPath, { force: true });
		} catch {}
		log.debug("Could not write the %s: %s", description, error instanceof Error ? error.message : String(error));
		return false;
	}
};
export { writeJsonFile };
